//! Metrics of the Office families the bundled fonts stand in for.
//!
//! A document was laid out against the family it names: its advance widths
//! decide where the lines break, its `hhea` metrics where the first baseline
//! sits. Where that family is one we substitute, the substitute's own metrics
//! move both, so each cluster advances and each line box is measured by the
//! named family's numbers instead — the letterforms stay the substitute's, the
//! words land where Word and PowerPoint put them. Widths are 1/1000 em for
//! `U+0020..=U+007E` plus the marks and accents a European document reaches
//! for; anything else keeps the substitute's own width. Each table is read off
//! the face Office draws the family with on macOS and checked against the font
//! programs Word and PowerPoint embed in their own exports.

use crate::{FontId, FontStore};

/// One family's own metrics, all in 1/1000 em.
#[derive(Debug)]
pub struct FamilyMetrics {
    /// `hhea` ascender, descender and line gap.
    pub ascent: i32,
    pub descent: i32,
    pub line_gap: i32,
    ascii: [u16; 95],
    extra: &'static [(u16, u16)],
}

struct FamilyEntry {
    family: &'static str,
    bold: bool,
    italic: bool,
    metrics: &'static FamilyMetrics,
}

/// The named family's width for `character`, in em.
pub fn family_advance(metrics: &FamilyMetrics, character: char) -> Option<f32> {
    let code = character as u32;
    let width = match code
        .checked_sub(0x20)
        .and_then(|index| metrics.ascii.get(index as usize))
    {
        Some(width) => *width,
        None => {
            let code = u16::try_from(code).ok()?;
            let index = metrics
                .extra
                .binary_search_by_key(&code, |(key, _)| *key)
                .ok()?;
            metrics.extra[index].1
        }
    };
    (width > 0).then(|| f32::from(width) / 1000.0)
}

/// The metrics of `family` at this weight and slope, when we have them.
pub fn family_metrics(family: &str, bold: bool, italic: bool) -> Option<&'static FamilyMetrics> {
    FAMILIES
        .iter()
        .find(|entry| entry.family == family && entry.bold == bold && entry.italic == italic)
        .map(|entry| entry.metrics)
}

/// Characters used to check whether a registered face matches a metric table.
const ADVANCE_SAMPLE: &str = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789 .,";

/// Preserve the face's kerning when its individual advances already match.
pub fn runs_at_own_widths(fonts: &FontStore, id: FontId, metrics: &FamilyMetrics) -> bool {
    let Ok(own) = fonts.metrics(id) else {
        return true;
    };
    let units = f32::from(own.units_per_em);
    if units <= 0.0 {
        return true;
    }
    for character in ADVANCE_SAMPLE.chars() {
        let Some(wanted) = family_advance(metrics, character) else {
            continue;
        };
        let Ok(Some(advance)) = fonts.advance_width(id, character) else {
            return false;
        };
        if (wanted - advance / units).abs() > 0.002 {
            return false;
        }
    }
    true
}

